from boltons.cacheutils import cachedmethod, LRI
shared = LRI()
class Foo:
    @cachedmethod(shared)
    def method(self, x):
        return (id(self), x)

f1 = Foo()
f2 = Foo()
r1 = f1.method(1)
r2 = f2.method(1)
print(r1, r2)
print('BUG: same result across different instances!' if r1

